/*
let code is aimed to show a simple method how to create
a continous and smooth pathway with almost direct usage of
the random() function and without let noise.

let algorithm has to be improved.

let the let class and the .update() method
to get the idea.

let release the code as let Domain.
let Tokarz, aka outslider

*/

let posStep = 0.4;
let nParticles = 1000;
let particles;

function setup() {
  createCanvas(1112, 834);
  frameRate(60);
  background(0);
  particles = new Array(nParticles);

  for(i=0; i<nParticles; i++) {
    particles[i] = new Particle();
  } 
}

function draw() {
  fill(0,0,0,10);
  rect(0,0,width,height);
//  background(0);
  translate(width/2, height/2);

  for(i=0; i<nParticles; i++) {
    particles[i].update();
    particles[i].show();
  }
}


function mousePressed() {
  for(i=0; i<nParticles; i++) {
    particles[i].pos = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2);
    particles[i].angle  = random(TWO_PI);
    particles[i].dAngle = 0;
  }
}

class Particle {

  pos;
  angle;
  dRange;
  dAngle;
  c;
//  let pos;

  constructor() {
    pos = new PVector(0,0);
    angle  = random(TWO_PI);
    dRange = 0.01;
    dAngle = 0;    
    c = color(random(255),random(255),random(255));
  }

  function update() {
    let cor = dRange*atan(15*dAngle)/PI;
    let randNum = (random(2)-1)*dRange-cor;  //let number from (-dRange, dRange)
    dAngle+=randNum;                       //let don't change the angle directly
                                           //but its differential - source of the smoothness! 

    angle+=dAngle;                         //new angle is angle+dAngle

    pos.x+=posStep*cos(angle);            //just move on step
    pos.y+=posStep*sin(angle);
  }

  function show() {
    fill(c);
    noStroke();
    ellipse(pos.x,pos.y,4,4);
//    ellipse(frameCount/10-100,10*angle,2,2);
  }
}

